//! Rendering the generated files: reviewable JSON (one entry per line), the
//! dataset `VERSION`, the per-rule report, and the USDA candidate map.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use crisp_core::ingredients::Dataset;
use eyre::Result;
use sha2::{Digest, Sha256};

use crate::assemble::Assembled;

/// A generated file: its path relative to the repository root, and content.
pub type Generated = Vec<(String, String)>;

/// The published dataset directory.
pub const DATASET_DIR: &str = "spec/ingredients";
/// The generated review artefacts.
pub const REPORT_DIR: &str = "tools/ingredients/report";

/// `[\n a,\n b\n]\n` with one compact JSON value per line.
fn lines_array<T: serde::Serialize>(items: &[T]) -> Result<String> {
    let rows: Vec<String> = items
        .iter()
        .map(serde_json::to_string)
        .collect::<Result<_, _>>()?;
    Ok(format!("[\n{}\n]\n", rows.join(",\n")))
}

/// `{\n "k": v,\n …}\n` with one compact JSON member per line.
fn lines_object<T: serde::Serialize>(map: &BTreeMap<String, T>) -> Result<String> {
    let rows: Vec<String> = map
        .iter()
        .map(|(k, v)| {
            Ok(format!(
                "{}: {}",
                serde_json::to_string(k)?,
                serde_json::to_string(v)?
            ))
        })
        .collect::<Result<_>>()?;
    if rows.is_empty() {
        return Ok("{}\n".to_owned());
    }
    Ok(format!("{{\n{}\n}}\n", rows.join(",\n")))
}

/// The dataset files, `VERSION` last (the SHA-256 of the others).
///
/// # Errors
/// When serialization fails.
pub fn dataset_files(dataset: &Dataset) -> Result<Generated> {
    let mut files: Generated = vec![
        (
            format!("{DATASET_DIR}/entries.json"),
            lines_array(&dataset.entries)?,
        ),
        (
            format!("{DATASET_DIR}/locales.json"),
            serde_json::to_string_pretty(&dataset.locales)? + "\n",
        ),
    ];
    let empty = BTreeMap::new();
    for shard in &dataset.locales.shards {
        let names = dataset.names.get(shard).unwrap_or(&empty);
        files.push((
            format!("{DATASET_DIR}/names/{shard}.json"),
            lines_object(names)?,
        ));
    }
    files.sort();
    let mut hasher = Sha256::new();
    for (path, content) in &files {
        hasher.update(path.as_bytes());
        hasher.update([0]);
        hasher.update(content.as_bytes());
        hasher.update([0]);
    }
    let version: String = hasher.finalize().iter().fold(String::new(), |mut s, b| {
        let _ = write!(s, "{b:02x}");
        s
    });
    files.push((format!("{DATASET_DIR}/VERSION"), version + "\n"));
    Ok(files)
}

/// The review report and candidate map.
///
/// # Errors
/// When serialization fails.
pub fn review_files(assembled: &Assembled, version: &str) -> Result<Generated> {
    let d = &assembled.dataset;
    let mut md = String::new();
    let _ = writeln!(md, "# Ingredient index import report\n");
    let _ = writeln!(
        md,
        "Generated by `just ingredients`; do not edit. Dataset version `{version}`.\n"
    );
    let _ = writeln!(md, "Entries: **{}**.\n", d.entries.len());
    let _ = writeln!(
        md,
        "## Included, by category\n\n| Category | Entries |\n|---|---|"
    );
    for (category, n) in &assembled.decisions.included {
        let _ = writeln!(md, "| {category} | {n} |");
    }
    let _ = writeln!(
        md,
        "\n## Excluded, by rule\n\n| Rule | Entries |\n|---|---|"
    );
    for (rule, n) in &assembled.decisions.excluded {
        let _ = writeln!(md, "| {rule} | {n} |");
    }
    let _ = writeln!(
        md,
        "\n## Names, by shard\n\n| Shard | Entries named | Spellings |\n|---|---|---|"
    );
    for shard in &d.locales.shards {
        let names = d.names.get(shard);
        let named = names.map_or(0, BTreeMap::len);
        let spellings: usize = names.map_or(0, |m| m.values().map(|n| 1 + n.aliases.len()).sum());
        let _ = writeln!(md, "| {shard} | {named} | {spellings} |");
    }
    let with_density = d.entries.iter().filter(|e| e.density.is_some()).count();
    let mut kinds: BTreeMap<(&str, bool), usize> = BTreeMap::new();
    for c in &assembled.candidates {
        *kinds.entry((c.kind.as_str(), c.accepted)).or_default() += 1;
    }
    let _ = writeln!(
        md,
        "\n## Density\n\nEntries with a density: **{with_density}**.\n"
    );
    let _ = writeln!(
        md,
        "| USDA match kind | Accepted | Candidates |\n|---|---|---|"
    );
    for ((kind, accepted), n) in &kinds {
        let _ = writeln!(
            md,
            "| {kind} | {} | {n} |",
            if *accepted { "yes" } else { "no" }
        );
    }
    let hinted = d
        .entries
        .iter()
        .filter(|e| !e.allergens.is_empty() || !e.diet_conflicts.is_empty())
        .count();
    let _ = writeln!(
        md,
        "\n## Hints\n\nEntries with allergen or diet hints: **{hinted}**."
    );
    let _ = writeln!(
        md,
        "\n## Retained\n\nPublished entries the sources no longer produce, kept unchanged: **{}**.",
        assembled.retained.len()
    );
    for slug in &assembled.retained {
        let _ = writeln!(md, "- `{slug}`");
    }
    let _ = writeln!(
        md,
        "\n## Unusable source keys\n\nNo slug-worthy characters: **{}**.",
        assembled.unusable.len()
    );
    for key in &assembled.unusable {
        let _ = writeln!(md, "- `{key}`");
    }
    Ok(vec![
        (format!("{REPORT_DIR}/report.md"), md),
        (
            format!("{REPORT_DIR}/usda-map.json"),
            lines_array(&assembled.candidates)?,
        ),
    ])
}

#[cfg(test)]
mod tests {
    use super::*;
    use crisp_core::ingredients::{Entry, LocaleTable};

    fn dataset() -> Dataset {
        Dataset {
            version: String::new(),
            locales: LocaleTable {
                shards: vec!["en-US".to_owned(), "ko-KR".to_owned()],
                fallback: BTreeMap::new(),
                last_resort: vec!["en-US".to_owned()],
            },
            entries: vec![Entry {
                slug: "kimchi".to_owned(),
                parent: None,
                category: "fermented".to_owned(),
                density: None,
                allergens: Vec::new(),
                diet_conflicts: Vec::new(),
                replaced_by: None,
                source: "off:en:kimchi".to_owned(),
            }],
            names: BTreeMap::new(),
        }
    }

    #[test]
    fn files_are_line_per_entry_and_versioned_by_content() {
        let files = dataset_files(&dataset()).expect("files");
        let paths: Vec<&str> = files.iter().map(|(p, _)| p.as_str()).collect();
        assert_eq!(
            paths,
            [
                "spec/ingredients/entries.json",
                "spec/ingredients/locales.json",
                "spec/ingredients/names/en-US.json",
                "spec/ingredients/names/ko-KR.json",
                "spec/ingredients/VERSION",
            ]
        );
        assert_eq!(
            files[0].1,
            "[\n{\"slug\":\"kimchi\",\"category\":\"fermented\",\"source\":\"off:en:kimchi\"}\n]\n"
        );
        assert_eq!(files[2].1, "{}\n");
        let again = dataset_files(&dataset()).expect("files");
        assert_eq!(files, again);
        let mut changed = dataset();
        changed.entries[0].category = "produce".to_owned();
        assert_ne!(dataset_files(&changed).expect("files")[4], files[4]);
    }

    #[test]
    fn the_report_counts_rules_shards_densities_and_hints() {
        use crate::select::Decisions;
        use crate::usda::Candidate;
        use crisp_core::ingredients::Names;
        use crisp_core::model::primitives::{OpenCode, Rational};

        let mut d = dataset();
        let mut dense = d.entries[0].clone();
        dense.slug = "milk".to_owned();
        dense.density = Some(Rational::new(103, 100));
        dense.diet_conflicts = vec![OpenCode::Other("vegan".to_owned())];
        let mut allergenic = d.entries[0].clone();
        allergenic.slug = "fish-sauce".to_owned();
        allergenic.allergens = vec![OpenCode::Other("fish".to_owned())];
        let mut allergenic_2 = allergenic.clone();
        allergenic_2.slug = "shrimp-paste".to_owned();
        let mut dense_2 = dense.clone();
        dense_2.slug = "cream".to_owned();
        d.entries.extend([dense, allergenic, allergenic_2, dense_2]);
        d.names.insert(
            "en-US".to_owned(),
            BTreeMap::from([(
                "kimchi".to_owned(),
                Names {
                    name: "kimchi".to_owned(),
                    aliases: vec!["kimchee".to_owned(), "gimchi".to_owned()],
                },
            )]),
        );
        let candidate = |kind: &str, accepted: bool| Candidate {
            slug: "milk".to_owned(),
            fdc_id: "1".to_owned(),
            description: "Milk".to_owned(),
            kind: kind.to_owned(),
            density: 1.03,
            accepted,
        };
        let assembled = Assembled {
            dataset: d,
            decisions: Decisions {
                included: BTreeMap::from([("dairy".to_owned(), 2)]),
                excluded: BTreeMap::from([("pattern: additive codes".to_owned(), 7)]),
            },
            candidates: vec![
                candidate("linked", true),
                candidate("linked", true),
                candidate("fuzzy", false),
            ],
            retained: vec!["old".to_owned()],
            unusable: vec!["off:en:김치".to_owned()],
        };
        let files = review_files(&assembled, "v1").expect("review");
        assert_eq!(files[0].0, "tools/ingredients/report/report.md");
        let md = &files[0].1;
        for line in [
            "Dataset version `v1`",
            "Entries: **5**.",
            "| dairy | 2 |",
            "| pattern: additive codes | 7 |",
            "| en-US | 1 | 3 |",
            "| ko-KR | 0 | 0 |",
            "Entries with a density: **2**.",
            "| linked | yes | 2 |",
            "| fuzzy | no | 1 |",
            "Entries with allergen or diet hints: **4**.",
            "kept unchanged: **1**.",
            "- `old`",
            "- `off:en:김치`",
        ] {
            assert!(md.contains(line), "missing {line:?} in:\n{md}");
        }
        assert_eq!(files[1].0, "tools/ingredients/report/usda-map.json");
        assert_eq!(files[1].1.lines().count(), 5);
    }
}
